package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.jsoup.Connection;
import org.jsoup.Jsoup;
import org.jsoup.helper.HttpConnection;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.FormElement;
import org.jsoup.nodes.Tag;
import org.jsoup.parser.Tag;
import org.jsoup.select.Elements;
import org.junit.*;
import org.junit.Test;
import static org.hamcrest.Matchers.*;
import static org.junit.Assert.*;

public class FormElement_formData_TriageGen0Test {

    @Test
    public void testFormData_emptyElementsList() {
        // Given
        FormElement formElement = new FormElement(Tag.valueOf("form"), "", null);

        // When
        List<Connection.KeyVal> formData = formElement.formData();

        // Then
        assertTrue(formData.isEmpty());
    }

    @Test
    public void testFormData_singleInputElement() {
        // Given
        Tag tag = Tag.valueOf("input");
        FormElement formElement = new FormElement(tag, "", null);
        formElement.addElement(new Element(tag));

        // When
        List<Connection.KeyVal> formData = formElement.formData();

        // Then
        assertThat(formData.size(), is(1));
        assertEquals("value", formData.get(0).key);
        assertEquals("value", formData.get(0).value);
    }

    @Test
    public void testFormData_inputElementWithDisabledAttribute() {
        // Given
        Tag tag = Tag.valueOf("input");
        FormElement formElement = new FormElement(tag, "", null);
        Element element = new Element(tag);
        element.attr("disabled", "disabled");
        formElement.addElement(element);

        // When
        List<Connection.KeyVal> formData = formElement.formData();

        // Then
        assertTrue(formData.isEmpty());
    }

    @Test
    public void testFormData_inputElementWithEmptyNameAttribute() {
        // Given
        Tag tag = Tag.valueOf("input");
        FormElement formElement = new FormElement(tag, "", null);
        Element element = new Element(tag);
        element.attr("name", "");
        formElement.addElement(element);

        // When
        List<Connection.KeyVal> formData = formElement.formData();

        // Then
        assertTrue(formData.isEmpty());
    }

    @Test
    public void testFormData_selectElementWithoutSelectedOption() {
        // Given
        Tag tag = Tag.valueOf("select");
        FormElement formElement = new FormElement(tag, "", null);
        Element select = new Element(tag);
        select.attr("name", "select");
        Element option = new Element(Tag.valueOf("option"));
        option.val("value");
        select.appendChild(option);
        formElement.addElement(select);

        // When
        List<Connection.KeyVal> formData = formElement.formData();

        // Then
        assertThat(formData.size(), is(1));
        assertEquals("select", formData.get(0).key);
        assertEquals("value", formData.get(0).value);
    }

    @Test
    public void testFormData_selectElementWithSelectedOption() {
        // Given
        Tag tag = Tag.valueOf("select");
        FormElement formElement = new FormElement(tag, "", null);
        Element select = new Element(tag);
        select.attr("name", "select");
        Element option = new Element(Tag.valueOf("option"));
        option.attr("selected", "selected");
        option.val("value");
        select.appendChild(option);
        Element option2 = new Element(Tag.valueOf("option"));
        option2.val("value2");
        select.appendChild(option2);
        formElement.addElement(select);

        // When
        List<Connection.KeyVal> formData = formElement.formData();

        // Then
        assertThat(formData.size(), is(2));
        assertEquals("select", formData.get(0).key);
        assertEquals("value", formData.get(0).value);
        assertEquals("select", formData.get(1).key);
        assertEquals("value2", formData.get(1).value);
    }

    @Test
    public void testFormData_checkboxElementWithCheckedAttribute() {
        // Given
        Tag tag = Tag.valueOf("input");
        FormElement formElement = new FormElement(tag, "", null);
        Element element = new Element(tag);
        element.attr("name", "checkbox");
        element.attr("type", "checkbox");
        element.attr("checked", "checked");
        formElement.addElement(element);

        // When
        List<Connection.KeyVal> formData = formElement.formData();

        // Then
        assertThat(formData.size(), is(1));
        assertEquals("checkbox", formData.get(0).key);
        assertEquals("on", formData.get(0).value);
    }

    @Test
    public void testFormData_checkboxElementWithoutCheckedAttribute() {
        // Given
        Tag tag = Tag.valueOf("input");
        FormElement formElement = new FormElement(tag, "", null);
        Element element = new Element(tag);
        element.attr("name", "checkbox");
        element.attr("type", "checkbox");
        formElement.addElement(element);

        // When
        List<Connection.KeyVal> formData = formElement.formData();

        // Then
        assertTrue(formData.isEmpty());
    }

    @Test
    public void testFormData_radioElementWithCheckedAttribute() {
        // Given
        Tag tag = Tag.valueOf("input");
        FormElement formElement = new FormElement(tag, "", null);
        Element element = new Element(tag);
        element.attr("name", "radio");
        element.attr("type", "radio");
        element.attr("checked", "checked");
        formElement.addElement(element);

        // When
        List<Connection.KeyVal> formData = formElement.formData();

        // Then
        assertThat(formData.size(), is(1));
        assertEquals("radio", formData.get(0).key);
        assertEquals("on", formData.get(0).value);
    }

    @Test
    public void testFormData_radioElementWithoutCheckedAttribute() {
        // Given
        Tag tag = Tag.valueOf("input");
        FormElement formElement = new FormElement(tag, "", null);
        Element element = new Element(tag);
        element.attr("name", "radio");
        element.attr("type", "radio");
        formElement.addElement(element);

        // When
        List<Connection.KeyVal> formData = formElement.formData();

        // Then
        assertTrue(formData.isEmpty());
    }
}
